<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(17, 24, 39, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e5eefb;
      --muted: #a8b3c7;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --focus: #facc15;
      --shadow: 0 24px 60px rgba(2, 8, 23, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.15), transparent 32%),
        linear-gradient(180deg, #020617 0%, #0f172a 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      top: 0.75rem;
      left: 0.75rem;
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: #ffffff;
      color: #111827;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 40rem);
      padding: 2rem;
      border: 1px solid var(--panel-border);
      border-radius: 1.5rem;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(1.8rem, 4vw, 2.4rem);
      line-height: 1.15;
    }

    .intro,
    .help-text,
    .status {
      color: var(--muted);
    }

    .intro {
      margin: 0 0 1.75rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      padding: 1.25rem;
      border: 1px solid rgba(125, 211, 252, 0.18);
      border-radius: 1rem;
      background: rgba(15, 23, 42, 0.72);
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
      min-inline-size: 0;
    }

    legend {
      margin-bottom: 0.65rem;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .required-mark {
      color: var(--accent);
    }

    .help-text {
      margin: 0 0 1rem;
      font-size: 0.96rem;
      line-height: 1.5;
    }

    .radio-option + .radio-option {
      margin-top: 0.75rem;
    }

    .radio-option label {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      width: 100%;
      padding: 0.95rem 1rem;
      border: 1px solid rgba(148, 163, 184, 0.25);
      border-radius: 0.95rem;
      background: rgba(30, 41, 59, 0.72);
      cursor: pointer;
      transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
    }

    .radio-option label:hover {
      border-color: rgba(125, 211, 252, 0.5);
      background: rgba(30, 41, 59, 0.9);
    }

    input[type="radio"] {
      width: 1.15rem;
      height: 1.15rem;
      margin: 0;
      accent-color: var(--accent-strong);
      flex: 0 0 auto;
    }

    input[type="radio"]:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .radio-option:has(input[type="radio"]:checked) label {
      border-color: rgba(56, 189, 248, 0.9);
      background: rgba(14, 116, 144, 0.24);
    }

    button[type="submit"] {
      justify-self: start;
      padding: 0.9rem 1.2rem;
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #082f49;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
    }

    button[type="submit"]:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      font-size: 0.96rem;
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.25rem;
      }

      .radio-option label {
        padding: 0.85rem 0.9rem;
      }

      button[type="submit"] {
        width: 100%;
        justify-self: stretch;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        transition: none !important;
        scroll-behavior: auto !important;
      }
    }

    @media (forced-colors: active) {
      .card,
      .form-field,
      .radio-option label,
      button[type="submit"] {
        border: 1px solid CanvasText;
      }

      button[type="submit"] {
        color: ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content" tabindex="-1">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification Preferences</h1>
      <p class="intro">Choose the way you would like to receive updates from us.</p>

      <form id="notification-form">
        <div class="form-field">
          <fieldset aria-describedby="notification-help">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-mark" aria-hidden="true">*</span>
            </legend>
            <p class="help-text" id="notification-help">Select one option before submitting.</p>

            <div class="radio-option">
              <label for="notify-email">
                <input id="notify-email" type="radio" name="notificationPreference" value="Email" required>
                <span>Email</span>
              </label>
            </div>

            <div class="radio-option">
              <label for="notify-sms">
                <input id="notify-sms" type="radio" name="notificationPreference" value="SMS" required>
                <span>SMS</span>
              </label>
            </div>

            <div class="radio-option">
              <label for="notify-push">
                <input id="notify-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                <span>Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
        <p class="status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const status = document.getElementById('form-status');
    const radios = form.querySelectorAll('input[name="notificationPreference"]');

    form.addEventListener('submit', (event) => {
      if (!form.reportValidity()) {
        status.textContent = 'Please choose a notification method.';
        return;
      }

      event.preventDefault();
      const formData = new FormData(form);
      const selection = formData.get('notificationPreference');
      status.textContent = 'Preference saved: ' + selection + '.';
    });

    radios.forEach((radio) => {
      radio.addEventListener('change', () => {
        status.textContent = '';
      });
    });
  </script>
</body>
</html>
