      radios.forEach((radio) => {
        radio.closest('.radio-option').classList.toggle('selected', radio.checked);
      });
    };

    form.addEventListener('submit', (event) => {
      if (!form.reportValidity()) {
        status.textContent = 'Please choose a notification method.';
        return;
